input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://brickschema.org/schema/>
SELECT ?point ?label ?ts
WHERE {
  ?ahu a brick:AirHandlingUnit ; rdfs:label "AHU02".
  ?point brick:isPointOf ?ahu .
  ?point rdf:type brick:ElectricalPower .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  OPTIONAL { ?point rdfs:label ?label }
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?ahu ?label WHERE {
  ?ahu a brick:AirHandlingUnit .
  OPTIONAL { ?ahu rdfs:label ?label }
}

PREFIX ref: <http://brickschema.org/schema/>
SELECT ?point ?class ?ts (STR(?point) as ?uri)
WHERE {
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point ?class [] }
}
LIMIT 50
